UPDATE tasks
SET research_trends = jsonb_build_array(
    '**Unified multimodal editors are replacing task-specific pipelines.** The field has moved beyond attention-only controls such as [Prompt-to-Prompt](/paper/2208.01626) and single-purpose instruction tuning toward models that share representations across understanding, generation, and editing. [Qwen-Image](/paper/2508.02324), [Emu3.5](/paper/2510.26583), and [NextFlow](/paper/2601.02204) combine multimodal encoders or unified autoregressive token streams with image generators, enabling open-ended, multi-image, and interleaved editing.',
    '**Editing is becoming a deliberative, post-trained process.** Hard spatial, knowledge, and multi-step instructions increasingly trigger explicit thinking, critique, reflection, or reinforcement learning instead of one-shot generation. [ReasonEdit](/paper/2511.22625) trains thinking–editing–reflection loops, [EditThinker](/paper/2512.05965) iteratively critiques and rewrites instructions for multiple editors, and [Uni-Edit](/paper/2605.21487) turns reasoning-intensive edits into unified-model tuning, with [RISEBench](/benchmark/risebench?task=image-editing) exposing the remaining gap.',
    '**Interactive speed is now designed together with source fidelity.** Rather than treating latency and preservation as afterthoughts, recent systems co-optimize native-resolution tokenization, compact conditioning, few-step distillation, and region-aware reuse. [Mage-Flow](/paper/2607.19064) pairs a 4B native-resolution stack with four-step Turbo variants, [VIBE](/paper/2601.02242) targets low-cost VLM-guided diffusion, and training-free [RegionE](/paper/2510.25590) skips redundant spatial and temporal computation while protecting untouched regions.'
),
updated_at = NOW()
WHERE slug = 'image-editing';
